	generator = "vertical_domino",
	interval_ms = 200,
	mode = "random",
	source = "whirly",
}

function M.get(name)
	local preset = catalog[name]
	return preset and vim.deepcopy(preset) or nil
end

function M.has(name)
	return type(name) == "string" and catalog[name] ~= nil
end

function M.names()
	local names = vim.tbl_keys(catalog)
	table.sort(names)
	return names
end

function M.count()
	return #M.names()
end

return M
